// ============================================================
// برق — موديول "باركود وطباعة"
// منقول من barcode-print.html بنفس المنطق حرفيًا (بدون أي تعديل في السلوك) —
// فقط: (1) لُفّ الكود جوه IIFE باسم BARQ_BC عشان يتفادى تصادم الأسماء العامة
// مع موديولات تانية جوه نفس الصفحة، (2) استدعاءات التهيئة
// (loadMasterFromStorage/renderTable) بقت بتتنفذ في mount() بدل وقت تحميل
// السكريبت مباشرة، لأن عناصر الـ DOM بتاعتها بتتحقن ديناميكيًا دلوقتي.
// المكتبات المساعدة (JsBarcode, PapaParse, xlsx) في app/js/vendor/ زي ما هي.
// ============================================================

var BARQ_BC_MARKUP = "<div class=\"bc-mod\">\n<div class=\"wrap\">\n\n  <div class=\"card\">\n    <h2>🖨️ إعدادات الطابعة والليبل</h2>\n    <div class=\"row\">\n      <div class=\"field\">\n        <label>مقاس الليبل</label>\n        <select id=\"labelSize\" onchange=\"BARQ_BC.onSizeChange()\">\n          <option value=\"55x40\" selected>55 × 40 مم (استيكرز الميزان الحراري)</option>\n          <option value=\"50x30\">50 × 30 مم</option>\n          <option value=\"40x30\">40 × 30 مم</option>\n          <option value=\"60x40\">60 × 40 مم</option>\n          <option value=\"30x20\">30 × 20 مم</option>\n          <option value=\"custom\">مقاس مخصص...</option>\n        </select>\n      </div>\n      <div class=\"field\" id=\"customW-wrap\" style=\"display:none\">\n        <label>العرض (مم)</label>\n        <input type=\"number\" id=\"customW\" value=\"50\" min=\"10\" max=\"200\">\n      </div>\n      <div class=\"field\" id=\"customH-wrap\" style=\"display:none\">\n        <label>الارتفاع (مم)</label>\n        <input type=\"number\" id=\"customH\" value=\"30\" min=\"10\" max=\"200\">\n      </div>\n      <div class=\"field\">\n        <label>نوع الباركود</label>\n        <select id=\"bcType\">\n          <option value=\"CODE128\">Code 128 (افتراضي — تلقائي)</option>\n          <option value=\"CODE128B\">Code 128 B</option>\n          <option value=\"CODE128A\">Code 128 A</option>\n          <option value=\"CODE128C\">Code 128 C</option>\n          <option value=\"EAN13\">EAN-13</option>\n          <option value=\"EAN8\">EAN-8</option>\n          <option value=\"CODE39\">Code 39</option>\n        </select>\n      </div>\n    </div>\n    <div style=\"font-size:11px;color:var(--muted)\">\n      * وصّل طابعة الـ Xprinter بالكمبيوتر (USB) وتأكد إن الدرايفر متثبت وظاهرة في \"الطابعات\" بالويندوز، وحطّها كطابعة افتراضية أو اخترها من نافذة الطباعة. الطباعة بتفتح نافذة منفصلة مضبوطة على نفس مقاس الليبل فوق.\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>🗂️ قاعدة بيانات المنتجات</h2>\n    <div class=\"sub\">ارفع شيت المنتجات المُصدَّر من فوديكس (أو أي CSV/Excel فيه name/barcode/price) — بيتفلتر أوتوماتيك على أصناف \"الوحدة\" (يُستبعد أي صنف بيباع بالوزن is_sold_by_weight)، وبيفضل محفوظ في المتصفح لحد ما ترفع نسخة جديدة.</div>\n    <div class=\"master-status empty\" id=\"masterStatus\">⚠️ لسه مفيش قاعدة منتجات متحملة — ارفع الشيت الأول</div>\n    <div class=\"btn-row\">\n      <label class=\"btn btn-ghost\" style=\"display:inline-block\">\n        📂 رفع شيت المنتجات (فوديكس / CSV / Excel)\n        <input type=\"file\" id=\"masterFileInput\" accept=\".csv,.xlsx,.xls\" style=\"display:none\" onchange=\"BARQ_BC.handleMasterImport(event)\">\n      </label>\n      <button class=\"btn btn-ghost\" onclick=\"BARQ_BC.clearMaster()\" id=\"clearMasterBtn\" style=\"display:none\">🗑️ مسح القاعدة</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>🔍 بحث / سكان المنتج</h2>\n    <div class=\"sub\">اكتب اسم أو باركود، أو امسح بالسكانر (بيدوس Enter تلقائي ويختار المطابقة بالظبط).</div>\n    <div class=\"search-wrap\">\n      <input id=\"searchBox\" placeholder=\"اسم الصنف أو الباركود...\" oninput=\"BARQ_BC.onSearchInput()\" onkeydown=\"BARQ_BC.onSearchKeydown(event)\" autocomplete=\"off\">\n      <div id=\"searchResults\"></div>\n    </div>\n    <div id=\"selPanel\"></div>\n    <button class=\"manual-toggle\" onclick=\"BARQ_BC.toggleManual()\" id=\"manualToggleBtn\" style=\"margin-top:10px\">➕ الصنف مش موجود في القاعدة؟ ضيفه يدوي</button>\n    <div id=\"manualPanel\" style=\"display:none;margin-top:10px\">\n      <div class=\"row\">\n        <div class=\"field\">\n          <label>اسم الصنف</label>\n          <input id=\"man-name\" placeholder=\"اسم الصنف\">\n        </div>\n        <div class=\"field\">\n          <label>الباركود / SKU</label>\n          <input id=\"man-bc\" placeholder=\"باركود يدوي\">\n        </div>\n        <div class=\"field\">\n          <label>السعر (جنيه)</label>\n          <input id=\"man-price\" type=\"number\" step=\"0.01\" placeholder=\"0.00\">\n        </div>\n      </div>\n      <div class=\"row\">\n        <div class=\"field\" style=\"max-width:180px\">\n          <label>التاريخ</label>\n          <input id=\"man-date\" type=\"date\">\n        </div>\n        <div class=\"field\" style=\"max-width:100px\">\n          <label>العدد</label>\n          <input id=\"man-qty\" type=\"number\" value=\"1\" min=\"1\">\n        </div>\n      </div>\n      <button class=\"btn btn-primary\" onclick=\"BARQ_BC.addManualItem()\">➕ إضافة للطباعة</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>📋 قائمة الطباعة (<span id=\"itemCount\">0</span> صنف)</h2>\n    <div id=\"itemsTableWrap\"><div class=\"empty-hint\">لسه ما فيش أصناف مضافة</div></div>\n    <div class=\"btn-row\" style=\"margin-top:12px\">\n      <button class=\"btn btn-danger\" onclick=\"BARQ_BC.clearAll()\">🗑️ مسح الكل</button>\n      <button class=\"btn btn-primary\" onclick=\"BARQ_BC.doPrint()\">🖨️ طباعة كل الليبلات</button>\n    </div>\n  </div>\n\n  <div class=\"card\">\n    <h2>👁️ معاينة</h2>\n    <div class=\"preview-wrap\" id=\"previewWrap\">\n      <div class=\"empty-hint\">هتظهر هنا معاينة لأول صنف في القائمة</div>\n    </div>\n  </div>\n\n</div>\n\n<div class=\"toast\" id=\"toast\"></div>\n</div>";

var BARQ_BC = (function () {

var ITEMS = [];
var LOGO_DATA_URI = "data:image/png;base64,";
var MASTER = {};       // key (barcode or sku) -> {name, sku, barcode, price}
var CURRENT_SEL = null; // currently selected master product, pending add

var LS_MASTER = 'barq_bc_master_v1';
var LS_DATES  = 'barq_bc_dates_v1';

function todayStr(){
  var d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
}

function loadDates(){
  try { return JSON.parse(localStorage.getItem(LS_DATES) || '{}'); } catch(e){ return {}; }
}
function saveDate(key, dateVal){
  if (!key || !dateVal) return;
  var d = loadDates();
  d[key] = dateVal;
  localStorage.setItem(LS_DATES, JSON.stringify(d));
}
function getSavedDate(key){
  var d = loadDates();
  return d[key] || '';
}

function toast(msg){
  var t = document.getElementById('toast');
  t.textContent = msg;
  t.classList.add('show');
  setTimeout(function(){ t.classList.remove('show'); }, 2000);
}

function onSizeChange(){
  var v = document.getElementById('labelSize').value;
  var isCustom = v === 'custom';
  document.getElementById('customW-wrap').style.display = isCustom ? 'block' : 'none';
  document.getElementById('customH-wrap').style.display = isCustom ? 'block' : 'none';
  renderPreview();
}

function getLabelDims(){
  var v = document.getElementById('labelSize').value;
  if (v === 'custom') {
    return {
      w: parseFloat(document.getElementById('customW').value) || 50,
      h: parseFloat(document.getElementById('customH').value) || 30
    };
  }
  var parts = v.split('x');
  return { w: parseFloat(parts[0]), h: parseFloat(parts[1]) };
}

// ── قاعدة بيانات المنتجات ──────────────────────────

function pick(row, keys){
  for (var k in row) {
    var kk = k.trim().toLowerCase();
    if (keys.indexOf(kk) !== -1 || keys.indexOf(k.trim()) !== -1) return row[k];
  }
  return '';
}

// بيحول أرقام عربي/فارسي لإنجليزي، وبيشيل رموز اتجاه النص المخفية (RTL/LTR marks, BOM, zero-width)
// اللي بتتلصق أحياناً من الإكسل أو الكيبورد العربي وبتبوّظ الباركود
function cleanBarcodeValue(v){
  var arabicDigits = '٠١٢٣٤٥٦٧٨٩';
  var persianDigits = '۰۱۲۳۴۵۶۷۸۹';
  return String(v == null ? '' : v)
    .replace(/[​-‏‪-‮﻿]/g, '')
    .replace(/[٠-٩]/g, function(d){ return String(arabicDigits.indexOf(d)); })
    .replace(/[۰-۹]/g, function(d){ return String(persianDigits.indexOf(d)); })
    .trim();
}

// أي باركود بيتطبع لازم يكون أرقام/حروف إنجليزية بس — نص عربي أو فاضي مش قابل للترميز خالص
function isValidBarcodeText(v){
  return /^[\x20-\x7E]+$/.test(String(v || ''));
}

function isSoldByWeight(row){
  var v = pick(row, ['is_sold_by_weight']);
  if (v === '' || v === undefined || v === null) return false; // شيت مبسط من غير العمود ده = وحدة
  var s = String(v).trim().toLowerCase();
  return s === '1' || s === 'true' || s === 'yes' || s === 'y';
}

function ingestMasterRows(rows){
  var added = 0, skippedWeight = 0, skippedNoCode = 0;
  rows.forEach(function(row){
    if (isSoldByWeight(row)) { skippedWeight++; return; }
    var name = pick(row, ['name','اسم','الصنف']);
    var sku = cleanBarcodeValue(pick(row, ['sku']));
    var barcode = cleanBarcodeValue(pick(row, ['barcode','باركود','bc']));
    // لو الباركود مش أرقام/حروف إنجليزية (فاضي أو نص عربي زي "بدون باركود") نعتبره مش موجود
    // ونرجع لكود المنتج (SKU) اللي بيبقى عادةً قابل للترميز
    if (!isValidBarcodeText(barcode)) barcode = '';
    if (!isValidBarcodeText(sku)) sku = '';
    var price = parseFloat(cleanBarcodeValue(pick(row, ['price','سعر','السعر']))) || 0;
    var key = barcode || sku;
    if (!key) { skippedNoCode++; return; }
    var prod = { name: name || key, sku: sku, barcode: barcode, price: price };
    MASTER[key] = prod;
    if (prod.sku) MASTER[prod.sku] = prod;
    if (prod.barcode) MASTER[prod.barcode] = prod;
    added++;
  });
  localStorage.setItem(LS_MASTER, JSON.stringify(MASTER));
  renderMasterStatus();
  var extra = [];
  if (skippedWeight) extra.push('استبعدنا ' + skippedWeight + ' صنف بيباع بالوزن');
  if (skippedNoCode) extra.push('استبعدنا ' + skippedNoCode + ' صنف من غير باركود ولا SKU صالح للطباعة');
  toast('✅ اتحمل ' + added + ' صنف بالوحدة' + (extra.length ? (' (' + extra.join(' — ') + ')') : ''));
}

// بعض الشيتات (زي شيت قوالب طباعة الرفوف) مش أعمدة عادية (اسم/باركود/سعر)،
// دي شكلها 3 صفوف لكل صنف (باركود بين قوسين، نفس الباركود كرقم، الاسم) وعمودين جنب بعض،
// وفيها صفوف فاضية كتير (placeholders). نكتشف الشكل ده تلقائي ونقرأه بطريقة مختلفة.
function looksLikeShelfGridSheet(matrix){
  if (!matrix || !matrix.length) return false;
  var c = matrix[0] && matrix[0][0];
  return typeof c === 'string' && /^\(.*\)$/.test(String(c).trim());
}

function parseShelfGridMatrix(matrix){
  var out = [];
  for (var i = 0; i + 2 < matrix.length; i += 4) {
    var numRow = matrix[i + 1] || [];
    var nameRow = matrix[i + 2] || [];
    [0, 2].forEach(function(colIdx){
      var bcRaw = numRow[colIdx];
      var nameRaw = nameRow[colIdx];
      if (bcRaw === undefined || bcRaw === null || bcRaw === '') return;
      if (nameRaw === undefined || nameRaw === null || nameRaw === '') return;
      out.push({ name: String(nameRaw).trim(), barcode: String(bcRaw).trim(), price: '' });
    });
  }
  return out;
}

function handleMasterImport(evt){
  var file = evt.target.files[0];
  if (!file) return;
  var ext = file.name.split('.').pop().toLowerCase();
  if (ext === 'csv') {
    Papa.parse(file, { header: true, skipEmptyLines: true, complete: function(res){ ingestMasterRows(res.data); } });
  } else {
    var reader = new FileReader();
    reader.onload = function(e){
      var wb = XLSX.read(new Uint8Array(e.target.result), { type: 'array' });
      var sheet = wb.Sheets[wb.SheetNames[0]];
      var matrix = XLSX.utils.sheet_to_json(sheet, { header: 1, defval: '' });
      if (looksLikeShelfGridSheet(matrix)) {
        toast('📋 شيت قوالب رفوف اتكشف — بيتقرا بدون سعر (تقدر تضيف السعر يدوي بعد الإضافة)');
        ingestMasterRows(parseShelfGridMatrix(matrix));
      } else {
        var json = XLSX.utils.sheet_to_json(sheet, { defval: '' });
        ingestMasterRows(json);
      }
    };
    reader.readAsArrayBuffer(file);
  }
  evt.target.value = '';
}

function clearMaster(){
  if (!confirm('مسح قاعدة المنتجات المحفوظة؟')) return;
  MASTER = {};
  localStorage.removeItem(LS_MASTER);
  renderMasterStatus();
  toast('🗑️ اتمسحت القاعدة');
}

function uniqueMasterCount(){
  var seen = {};
  Object.keys(MASTER).forEach(function(k){
    var p = MASTER[k];
    var id = p.barcode || p.sku;
    seen[id] = true;
  });
  return Object.keys(seen).length;
}

function renderMasterStatus(){
  var el = document.getElementById('masterStatus');
  var n = uniqueMasterCount();
  if (n > 0) {
    el.className = 'master-status';
    el.innerHTML = '✅ متحمّل <b>' + n + '</b> صنف بالوحدة — جاهز للبحث والسكان';
    document.getElementById('clearMasterBtn').style.display = 'inline-block';
  } else {
    el.className = 'master-status empty';
    el.innerHTML = '⚠️ لسه مفيش قاعدة منتجات متحملة — ارفع الشيت الأول';
    document.getElementById('clearMasterBtn').style.display = 'none';
  }
}

function loadMasterFromStorage(){
  try {
    var saved = JSON.parse(localStorage.getItem(LS_MASTER) || '{}');
    MASTER = saved || {};
  } catch(e){ MASTER = {}; }
  renderMasterStatus();
}

// ── بحث / سكان ──────────────────────────────────────

function uniqueMasterList(){
  var seen = {}, out = [];
  Object.keys(MASTER).forEach(function(k){
    var p = MASTER[k];
    var id = p.barcode || p.sku;
    if (seen[id]) return;
    seen[id] = true;
    out.push(p);
  });
  return out;
}

function onSearchInput(){
  var q = document.getElementById('searchBox').value.trim().toLowerCase();
  var box = document.getElementById('searchResults');
  if (!q) { box.innerHTML = ''; return; }
  var list = uniqueMasterList().filter(function(p){
    return p.name.toLowerCase().indexOf(q) !== -1 ||
           (p.barcode||'').toLowerCase().indexOf(q) !== -1 ||
           (p.sku||'').toLowerCase().indexOf(q) !== -1;
  }).slice(0, 8);

  if (!list.length) {
    box.innerHTML = '<div class="search-hint">مفيش نتائج مطابقة — تقدر تضيفه يدوي تحت</div>';
    return;
  }
  box.innerHTML = '<div class="search-results">' + list.map(function(p){
    var id = (p.barcode || p.sku).replace(/'/g, "\\'");
    return '<div class="sr-item" onclick="BARQ_BC.selectProduct(\'' + id + '\')">' +
      '<span class="sr-name">' + escapeHtml(p.name) + '</span>' +
      '<span class="sr-meta">' + escapeHtml(p.barcode || p.sku) + ' · ' + p.price.toFixed(2) + ' ج.م</span>' +
    '</div>';
  }).join('') + '</div>';
}

function onSearchKeydown(evt){
  if (evt.key !== 'Enter') return;
  var q = cleanBarcodeValue(document.getElementById('searchBox').value);
  if (!q) return;
  // سكانر بيدوس Enter بعد ما يكتب الباركود كامل — نطابق مطابقة تامة
  var exact = MASTER[q];
  if (exact) {
    selectProduct(exact.barcode || exact.sku);
  } else {
    toast('⚠️ الباركود ده مش موجود في القاعدة');
  }
}

function selectProduct(key){
  var p = MASTER[key];
  if (!p) return;
  CURRENT_SEL = p;
  var dateKey = p.barcode || p.sku;
  var savedDate = getSavedDate(dateKey);
  document.getElementById('searchResults').innerHTML = '';
  document.getElementById('searchBox').value = '';
  document.getElementById('selPanel').innerHTML =
    '<div class="sel-panel">' +
      '<div class="sel-name">' + escapeHtml(p.name) + '</div>' +
      '<div class="row">' +
        '<div class="field"><label>الباركود</label><input value="' + escapeHtml(p.barcode || p.sku) + '" readonly></div>' +
        '<div class="field"><label>السعر (من الشيت)</label><input value="' + p.price.toFixed(2) + ' ج.م" readonly></div>' +
      '</div>' +
      '<div class="row">' +
        '<div class="field" style="max-width:180px"><label>التاريخ</label><input id="sel-date" type="date" value="' + savedDate + '"></div>' +
        '<div class="field" style="max-width:100px"><label>العدد</label><input id="sel-qty" type="number" value="1" min="1"></div>' +
      '</div>' +
      (savedDate ? '<div style="font-size:11px;color:var(--muted);margin-bottom:8px">📌 التاريخ ده آخر تاريخ اتسجل لنفس الصنف — عدّله لو محتاج</div>' : '') +
      '<button class="btn btn-primary" onclick="BARQ_BC.addSelectedToQueue()">➕ إضافة للطباعة</button>' +
    '</div>';
}

function addSelectedToQueue(){
  if (!CURRENT_SEL) return;
  var date = document.getElementById('sel-date').value;
  var qty = parseInt(document.getElementById('sel-qty').value) || 1;
  if (!date) { toast('⚠️ اختار التاريخ الأول'); return; }
  var dateKey = CURRENT_SEL.barcode || CURRENT_SEL.sku;
  saveDate(dateKey, date);
  ITEMS.push({ name: CURRENT_SEL.name, barcode: CURRENT_SEL.barcode || CURRENT_SEL.sku, price: CURRENT_SEL.price, qty: qty, date: date });
  toast('✅ اتضاف: ' + CURRENT_SEL.name);
  CURRENT_SEL = null;
  document.getElementById('selPanel').innerHTML = '';
  document.getElementById('searchBox').focus();
  renderTable();
}

// ── إضافة يدوية (fallback) ─────────────────────────

function toggleManual(){
  var p = document.getElementById('manualPanel');
  p.style.display = p.style.display === 'none' ? 'block' : 'none';
  if (p.style.display === 'block') document.getElementById('man-date').value = todayStr();
}

function addManualItem(){
  var name = document.getElementById('man-name').value.trim();
  var bc = cleanBarcodeValue(document.getElementById('man-bc').value);
  var price = parseFloat(document.getElementById('man-price').value) || 0;
  var date = document.getElementById('man-date').value;
  var qty = parseInt(document.getElementById('man-qty').value) || 1;

  if (!bc) { toast('⚠️ لازم تدخل باركود أو SKU'); return; }
  if (!isValidBarcodeText(bc)) { toast('⚠️ الباركود لازم يكون أرقام أو حروف إنجليزية بس (مش عربي)'); return; }
  if (!name) name = bc;

  if (date) saveDate(bc, date);
  ITEMS.push({ name: name, barcode: bc, price: price, qty: qty, date: date });
  document.getElementById('man-name').value = '';
  document.getElementById('man-bc').value = '';
  document.getElementById('man-price').value = '';
  document.getElementById('man-qty').value = '1';
  document.getElementById('man-date').value = todayStr();
  document.getElementById('man-bc').focus();
  renderTable();
  toast('✅ اتضاف: ' + name);
}

// ── قائمة الطباعة ───────────────────────────────────

function removeItem(idx){
  ITEMS.splice(idx, 1);
  renderTable();
}

function clearAll(){
  if (!ITEMS.length) return;
  if (!confirm('متأكد عايز تمسح كل القائمة؟')) return;
  ITEMS = [];
  renderTable();
}

function renderTable(){
  var wrap = document.getElementById('itemsTableWrap');
  document.getElementById('itemCount').textContent = ITEMS.length;
  if (!ITEMS.length) {
    wrap.innerHTML = '<div class="empty-hint">لسه ما فيش أصناف مضافة</div>';
    renderPreview();
    return;
  }
  var rows = ITEMS.map(function(it, i){
    return '<tr>' +
      '<td>' + escapeHtml(it.name) + '</td>' +
      '<td>' + escapeHtml(it.barcode) + '</td>' +
      '<td>' + it.price.toFixed(2) + '</td>' +
      '<td><input type="date" value="' + (it.date||'') + '" onchange="BARQ_BC.updateDate(' + i + ',this.value)"></td>' +
      '<td><input type="number" min="1" class="qty-input" value="' + it.qty + '" onchange="BARQ_BC.updateQty(' + i + ',this.value)"></td>' +
      '<td><button class="rm-btn" onclick="BARQ_BC.removeItem(' + i + ')">✕</button></td>' +
    '</tr>';
  }).join('');
  wrap.innerHTML = '<table><thead><tr><th>الاسم</th><th>الباركود</th><th>السعر</th><th>التاريخ</th><th>العدد</th><th></th></tr></thead><tbody>' + rows + '</tbody></table>';
  renderPreview();
}

function updateQty(idx, val){
  ITEMS[idx].qty = parseInt(val) || 1;
}

function updateDate(idx, val){
  ITEMS[idx].date = val;
  if (val) saveDate(ITEMS[idx].barcode, val);
}

function renderPreview(){
  var wrap = document.getElementById('previewWrap');
  if (!ITEMS.length) {
    wrap.innerHTML = '<div class="empty-hint">هتظهر هنا معاينة لأول صنف في القائمة</div>';
    return;
  }
  var dims = getLabelDims();
  var pxW = dims.w * 3.78, pxH = dims.h * 3.78; // approx mm -> px at 96dpi
  var it = ITEMS[0];
  wrap.innerHTML =
    '<div class="label-preview" style="width:' + pxW + 'px;height:' + pxH + 'px">' +
      '<img class="lp-logo" src="' + LOGO_DATA_URI + '" alt="">' +
      '<div class="lp-name">' + escapeHtml(it.name) + '</div>' +
      (it.date ? '<div class="lp-date">' + it.date + '</div>' : '') +
      '<svg id="prevSvg" style="height:' + Math.max(24, pxH * 0.35) + 'px;width:auto;max-width:90%"></svg>' +
      '<div class="lp-price">' + it.price.toFixed(2) + ' ج.م</div>' +
    '</div>';
  var chosenType = document.getElementById('bcType').value;
  try {
    JsBarcode('#prevSvg', it.barcode, {
      format: chosenType,
      width: 1.3, height: 40, displayValue: true, fontSize: 10, margin: 2
    });
  } catch (e) {
    // النوع المختار (EAN-13/EAN-8/Code 39) بيرفض أي كود مش مطابق للمواصفة بتاعته بالظبط —
    // نرجع لـ Code 128 اللي بيقبل أي طول/شكل رقم، بدل ما نوقف المستخدم بخطأ
    try {
      JsBarcode('#prevSvg', it.barcode, {
        format: 'CODE128', width: 1.3, height: 40, displayValue: true, fontSize: 10, margin: 2
      });
    } catch (e2) {
      document.getElementById('prevSvg').outerHTML = '<div style="color:var(--red);font-size:11px">تعذّر رسم الباركود — تفاصيل: ' + escapeHtml(String(e2)) + '</div>';
    }
  }
}

function doPrint(){
  if (!ITEMS.length) { toast('⚠️ القائمة فاضية'); return; }
  var dims = getLabelDims();
  var bcType = document.getElementById('bcType').value;

  var labelsHTML = '';
  ITEMS.forEach(function(it){
    for (var i = 0; i < it.qty; i++) {
      var svgId = 'bc_' + Math.random().toString(36).slice(2);
      labelsHTML +=
        '<div class="label">' +
          '<img class="llogo" src="' + LOGO_DATA_URI + '" alt="">' +
          '<div class="lname">' + escapeHtml(it.name) + '</div>' +
          (it.date ? '<div class="ldate">' + escapeHtml(it.date) + '</div>' : '') +
          '<svg id="' + svgId + '" class="barcode" jsbarcode-value="' + escapeHtml(it.barcode) + '" jsbarcode-format="' + bcType + '" jsbarcode-width="1.3" jsbarcode-height="40" jsbarcode-displayvalue="true" jsbarcode-fontsize="9" jsbarcode-margin="0"></svg>' +
          '<div class="lprice">' + it.price.toFixed(2) + ' ج.م</div>' +
        '</div>';
    }
  });

  var win = window.open('', '_blank');
  win.document.write(
    '<html dir="rtl" lang="ar"><head><meta charset="UTF-8"><title>طباعة الباركود</title>' +
    '<script>' + document.getElementById("lib-jsbarcode").textContent + '<\/script>' +
    '<style>' +
    '@page{size:' + dims.w + 'mm ' + dims.h + 'mm;margin:0}' +
    '*{box-sizing:border-box;margin:0;padding:0;font-family:Tahoma,Arial,sans-serif}' +
    '.label{width:' + dims.w + 'mm;height:' + dims.h + 'mm;display:flex;flex-direction:column;align-items:center;justify-content:center;overflow:hidden;page-break-after:always;text-align:center;padding:1mm}' +
    '.llogo{height:4mm;width:auto;margin-bottom:0.5mm}' +
    '.lname{font-size:4.2mm;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:98%}' +
    '.ldate{font-size:2mm;color:#444}' +
    '.lprice{font-size:7.2mm;font-weight:900}' +
    'svg.barcode{height:' + Math.max(6, dims.h * 0.35) + 'mm;width:auto;max-width:90%}' +
    '</style></head><body>' +
    labelsHTML +
    '<scr' + 'ipt>' +
    'window.onload=function(){' +
      // كل SVG بياخد قيمته من jsbarcode-value وشكله من jsbarcode-format، بدل ما تتكتب كنص عادي جوه خلية —
      // بنلف عليها واحدة واحدة (مش JsBarcode(".barcode").init() اللي بتوقف تماماً لو صنف واحد بس فيه كود غير صالح)
      // عشان لو صنف واحد فشل، الباقي يتطبع عادي بدل ما الصفحة كلها تبوظ
      'document.querySelectorAll("svg.barcode").forEach(function(el){' +
        'var bcVal = el.getAttribute("jsbarcode-value");' +
        'var opts = {' +
          'width: parseFloat(el.getAttribute("jsbarcode-width")), ' +
          'height: parseFloat(el.getAttribute("jsbarcode-height")), ' +
          'displayValue: el.getAttribute("jsbarcode-displayvalue") === "true", ' +
          'fontSize: parseFloat(el.getAttribute("jsbarcode-fontsize")), ' +
          'margin: parseFloat(el.getAttribute("jsbarcode-margin"))' +
        '};' +
        'try{JsBarcode(el, bcVal, Object.assign({format: el.getAttribute("jsbarcode-format")}, opts));}' +
        'catch(e){' +
          'try{JsBarcode(el, bcVal, Object.assign({format:"CODE128"}, opts));}' +
          'catch(e2){el.outerHTML="<div style=\\"color:red;font-size:8px\\">تعذّر رسم الباركود: "+String(e2).replace(/</g,"&lt;")+"</div>";}' +
        '}' +
      '});' +
      'setTimeout(function(){window.print();}, 200);' +
    '};' +
    '</scr' + 'ipt>' +
    '</body></html>'
  );
  win.document.close();
}

function escapeHtml(s){
  return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

  function mount(container) {
    container.innerHTML = BARQ_BC_MARKUP;
    loadMasterFromStorage();
    renderTable();
  }

  return {
    handleMasterImport: handleMasterImport,
    onSizeChange: onSizeChange,
    addManualItem: addManualItem,
    clearAll: clearAll,
    clearMaster: clearMaster,
    doPrint: doPrint,
    toggleManual: toggleManual,
    onSearchInput: onSearchInput,
    onSearchKeydown: onSearchKeydown,
    selectProduct: selectProduct,
    addSelectedToQueue: addSelectedToQueue,
    updateDate: updateDate,
    updateQty: updateQty,
    removeItem: removeItem,
    mount: mount
  };
})();

window.BARQ_MODULES = window.BARQ_MODULES || {};
window.BARQ_MODULES['barcode'] = { mount: BARQ_BC.mount };
